/** Test helpers: hidden truth generated by the same Python generator the installer uses. */
import { execFileSync } from 'node:child_process'
import { existsSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { loadTruth } from './truth.ts'

export const python = process.platform === 'win32' ? 'python' : 'python3'
const here = dirname(fileURLToPath(import.meta.url))

/** Write (once) and load a truth file next to a run directory. */
export function truthFor(directory: string, seed = 1, load = 'L2') {
  const path = `${directory}.evaluator/truth.json`
  if (!existsSync(path)) {
    mkdirSync(dirname(path), { recursive: true })
    execFileSync(python, [join(here, 'truth.py'), '--seed', String(seed), '--load', load, '--output', path], { env: process.env })
  }
  return { path, truth: loadTruth(path) }
}
/** Generate the archive for a run directory. */
export function archiveFor(directory: string, truthPath: string) {
  const history = join(directory, 'public/history'), answers = `${directory}.evaluator/archive-answers.json`
  if (!existsSync(join(history, 'history.sqlite')))
    execFileSync(python, [join(here, 'make-data.py'), '--directory', history, '--truth', truthPath, '--answers', answers], { env: process.env })
  return { history, answers }
}
